import Foundation

// MARK: - JSONValue

/// The value an undeclared watch binds. A watch with a `shape:` decodes into a
/// generated struct instead and never touches this.
enum JSONValue: Equatable {
    case null
    case bool(Bool)
    case int(Int)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

extension JSONValue: Decodable {
    init(from decoder: Decoder) throws {
        if let c = try? decoder.singleValueContainer() {
            if c.decodeNil() {
                self = .null
                return
            }
            if let v = try? c.decode(Bool.self) {
                self = .bool(v)
                return
            }
            if let v = try? c.decode(Int.self) {
                self = .int(v)
                return
            }
            if let v = try? c.decode(Double.self) {
                self = .double(v)
                return
            }
            if let v = try? c.decode(String.self) {
                self = .string(v)
                return
            }
            if let v = try? c.decode([JSONValue].self) {
                self = .array(v)
                return
            }
            if let v = try? c.decode([String: JSONValue].self) {
                self = .object(v)
                return
            }
        }
        self = .null
    }

    static func parse(_ text: String) -> JSONValue {
        guard let data = text.data(using: .utf8) else { return .null }
        return (try? JSONDecoder().decode(JSONValue.self, from: data)) ?? .null
    }
}

extension JSONValue {
    init(_ v: Bool) { self = .bool(v) }
    init(_ v: Int) { self = .int(v) }
    init(_ v: Double) { self = .double(v) }
    init(_ v: String) { self = .string(v) }

    subscript(key: String) -> JSONValue {
        if case .object(let o) = self { return o[key] ?? .null }
        return .null
    }

    subscript(index: Int) -> JSONValue {
        if case .array(let a) = self, a.indices.contains(index) { return a[index] }
        return .null
    }

    var exists: Bool { self != .null }

    var asBool: Bool {
        switch self {
        case .bool(let b): return b
        case .int(let i): return i != 0
        case .double(let d): return d != 0
        case .string(let s): return !s.isEmpty
        case .array(let a): return !a.isEmpty
        case .object(let o): return !o.isEmpty
        case .null: return false
        }
    }

    var asInt: Int {
        switch self {
        case .int(let i): return i
        // Int(Double) traps outside Int's range, and the double came from
        // whatever the watch printed.
        case .double(let d): return Int(exactly: d.rounded()) ?? 0
        case .bool(let b): return b ? 1 : 0
        case .string(let s): return Int(s) ?? 0
        default: return 0
        }
    }

    var asDouble: Double {
        switch self {
        case .double(let d): return d
        case .int(let i): return Double(i)
        case .bool(let b): return b ? 1 : 0
        case .string(let s): return Double(s) ?? 0
        default: return 0
        }
    }

    var asString: String {
        switch self {
        case .string(let s): return s
        case .int(let i): return String(i)
        case .double(let d):
            if d == d.rounded(), let i = Int(exactly: d) { return String(i) }
            return String(d)
        case .bool(let b): return String(b)
        case .null: return ""
        case .array, .object: return ""
        }
    }

    var asArray: [JSONValue] {
        if case .array(let a) = self { return a }
        return []
    }

    var size: Int {
        switch self {
        case .array(let a): return a.count
        case .object(let o): return o.count
        case .string(let s): return s.count
        default: return 0
        }
    }

    func contains(_ needle: JSONValue) -> Bool { asArray.contains(needle) }
}

// MARK: - Boxes

/// A value one thread fills in and another reads. Used where a completion
/// handler outlives the call that started it.
private final class Box<T> {
    private var value: T
    private let lock = NSLock()

    init(_ initial: T) { value = initial }

    func mutate(_ body: (inout T) -> Void) {
        lock.lock()
        defer { lock.unlock() }
        body(&value)
    }

    var current: T {
        lock.lock()
        defer { lock.unlock() }
        return value
    }
}

// MARK: - Watches

struct RunOutcome {
    var ok = false
    var code = -1
    var out = ""
    var err = ""
}

struct HTTPOutcome {
    var ok = false
    var status = 0
    var out = ""
}

struct LaunchAgentOutcome {
    var installed = false
    var loaded = false
    var running = false
    var enabled = true
    var pid = 0
    var label = ""
    var plist = "" // expanded
}

/// Where a user's own LaunchAgents live, and how launchctl is told about them.
enum Launchd {
    /// Read at runtime because it is the one part of addressing an agent that
    /// differs between Macs: 501 is only the first account a Mac creates.
    static var domain: String { "gui/\(getuid())" }

    static func target(_ label: String) -> String { domain + "/" + label }

    /// launchctl is handed argv directly, with no shell to expand a tilde.
    static func expand(_ path: String) -> String { (path as NSString).expandingTildeInPath }

    /// Whether launchd's disabled database holds the label off, which is what
    /// keeps it from loading at login. A label it has no entry for is enabled.
    /// Older macOS writes `=> true` where 27 writes `=> disabled`.
    static func disabled(_ label: String) -> Bool {
        let printed = Watcher.run(["launchctl", "print-disabled", domain], timeout: 10)
        let key = "\"" + label + "\" => "
        for line in printed.out.split(separator: "\n") {
            let field = line.trimmingCharacters(in: .whitespaces)
            guard field.hasPrefix(key) else { continue }
            let value = field.dropFirst(key.count)
            return value == "disabled" || value == "true"
        }
        return false
    }
}

enum Watcher {
    /// Output past this is read and dropped, so a child that never stops
    /// printing neither stalls on a full pipe nor grows the app without bound.
    static let outputCap = 4 << 20

    /// Runs argv directly — never a shell. /usr/bin/env performs the PATH
    /// lookup, which a LaunchAgent's minimal environment would otherwise miss.
    ///
    /// The child leads its own process group, so a timeout stops everything it
    /// started. Once it exits, descendants still holding its pipes get a second
    /// to let go and are then left alone: a poll does not wait on a daemon.
    static func run(_ argv: [String], timeout: TimeInterval? = nil) -> RunOutcome {
        guard !argv.isEmpty else { return RunOutcome() }
        var outFDs: [Int32] = [-1, -1]
        var errFDs: [Int32] = [-1, -1]
        guard pipe(&outFDs) == 0 else { return failed("pipe: " + String(cString: strerror(errno))) }
        guard pipe(&errFDs) == 0 else {
            outFDs.forEach { close($0) }
            return failed("pipe: " + String(cString: strerror(errno)))
        }

        var actions: posix_spawn_file_actions_t?
        posix_spawn_file_actions_init(&actions)
        defer { posix_spawn_file_actions_destroy(&actions) }
        posix_spawn_file_actions_addopen(&actions, 0, "/dev/null", O_RDONLY, 0)
        posix_spawn_file_actions_adddup2(&actions, outFDs[1], 1)
        posix_spawn_file_actions_adddup2(&actions, errFDs[1], 2)

        var attr: posix_spawnattr_t?
        posix_spawnattr_init(&attr)
        defer { posix_spawnattr_destroy(&attr) }
        // CLOEXEC_DEFAULT keeps the app's own descriptors out of the child.
        posix_spawnattr_setflags(&attr, Int16(POSIX_SPAWN_SETPGROUP | POSIX_SPAWN_CLOEXEC_DEFAULT
            | POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK))
        posix_spawnattr_setpgroup(&attr, 0)
        var all = sigset_t()
        sigfillset(&all)
        posix_spawnattr_setsigdefault(&attr, &all)
        var none = sigset_t()
        sigemptyset(&none)
        posix_spawnattr_setsigmask(&attr, &none)

        var cargs: [UnsafeMutablePointer<CChar>?] = (["/usr/bin/env"] + argv).map { strdup($0) } + [nil]
        defer { cargs.forEach { free($0) } }
        var pid: pid_t = 0
        let spawned = posix_spawn(&pid, "/usr/bin/env", &actions, &attr, &cargs, environ)
        close(outFDs[1])
        close(errFDs[1])
        guard spawned == 0 else {
            close(outFDs[0])
            close(errFDs[0])
            return failed(String(cString: strerror(spawned)))
        }

        // Both pipes drain at once. Reading one to EOF and then the other
        // deadlocks a child that fills the second pipe's buffer meanwhile.
        var fds = [outFDs[0], errFDs[0]].map { fd -> pollfd in
            _ = fcntl(fd, F_SETFL, fcntl(fd, F_GETFL) | O_NONBLOCK)
            return pollfd(fd: fd, events: Int16(POLLIN), revents: 0)
        }
        var captured = [Capture(), Capture()]
        let started = Date()
        var status: Int32 = 0
        var exitedAt: Date?
        var termAt: Date?
        var killed = false
        while true {
            let open = fds.contains { $0.fd >= 0 }
            if let exitedAt, !open || Date().timeIntervalSince(exitedAt) > 1 { break }
            if open {
                _ = poll(&fds, nfds_t(fds.count), 50)
            } else {
                usleep(20_000)
            }
            for i in fds.indices where fds[i].fd >= 0 && fds[i].revents != 0 {
                if !captured[i].drain(fds[i].fd) {
                    close(fds[i].fd)
                    fds[i].fd = -1
                }
            }
            if exitedAt == nil, waitpid(pid, &status, WNOHANG) == pid { exitedAt = Date() }
            guard exitedAt == nil, let timeout else { continue }
            if termAt == nil, Date().timeIntervalSince(started) >= timeout {
                killpg(pid, SIGTERM)
                termAt = Date()
            } else if let termAt, !killed, Date().timeIntervalSince(termAt) >= 2 {
                killpg(pid, SIGKILL)
                killed = true
            }
        }
        fds.filter { $0.fd >= 0 }.forEach { close($0.fd) }

        var notes: [String] = []
        if let timeout, termAt != nil { notes.append("perch: stopped after \(seconds(timeout)), its timeout") }
        for (i, name) in ["stdout", "stderr"].enumerated() where captured[i].dropped > 0 {
            notes.append("perch: \(name) cut at \(outputCap) bytes; \(captured[i].dropped) more dropped")
        }
        // A wait status: the low seven bits are the signal, zero for an exit.
        let signal = status & 0x7f
        let code = termAt != nil ? -1 : Int(signal == 0 ? (status >> 8) & 0xff : signal)
        var err = String(decoding: captured[1].data, as: UTF8.self)
        for note in notes {
            if !err.isEmpty, !err.hasSuffix("\n") { err += "\n" }
            err += note + "\n"
        }
        return RunOutcome(
            ok: code == 0,
            code: code,
            out: String(decoding: captured[0].data, as: UTF8.self),
            err: err
        )
    }

    private static func failed(_ why: String) -> RunOutcome {
        RunOutcome(ok: false, code: -1, out: "", err: why)
    }

    private static func seconds(_ t: TimeInterval) -> String {
        t == t.rounded() ? "\(Int(t))s" : "\(t)s"
    }

    private struct Capture {
        var data = Data()
        var dropped = 0

        /// Reads what the pipe holds now. False once it reaches EOF.
        mutating func drain(_ fd: Int32) -> Bool {
            var chunk = [UInt8](repeating: 0, count: 1 << 16)
            while true {
                let n = read(fd, &chunk, chunk.count)
                if n > 0 {
                    let room = max(0, Watcher.outputCap - data.count)
                    data.append(contentsOf: chunk[0..<min(n, room)])
                    dropped += max(0, n - room)
                } else if n < 0, errno == EINTR {
                    continue
                } else {
                    return n < 0 && errno == EAGAIN
                }
            }
        }
    }

    static func http(_ urlString: String) -> HTTPOutcome {
        guard let url = URL(string: urlString) else { return HTTPOutcome() }
        // Boxed because the wait below can time out while the request is still
        // in flight, leaving the handler to write after this call has returned.
        let box = Box(HTTPOutcome())
        let done = DispatchSemaphore(value: 0)
        var request = URLRequest(url: url)
        request.timeoutInterval = 5
        URLSession.shared.dataTask(with: request) { data, response, _ in
            box.mutate { outcome in
                if let http = response as? HTTPURLResponse {
                    outcome.status = http.statusCode
                    outcome.ok = (200..<300).contains(http.statusCode)
                }
                if let data { outcome.out = String(data: data, encoding: .utf8) ?? "" }
            }
            done.signal()
        }.resume()
        _ = done.wait(timeout: .now() + 10)
        return box.current
    }

    static func exists(_ path: String) -> Bool {
        FileManager.default.fileExists(atPath: (path as NSString).expandingTildeInPath)
    }

    /// `launchctl print` exiting 0 says launchd knows the label, which is not
    /// the same as the job having a process: one that has run and exited is
    /// still loaded. The top-level `state =` line is what separates the two,
    /// and it is exactly one tab in — deeper ones describe the job's endpoints
    /// and are active whether or not the job itself is.
    static func launchAgent(label: String, plist: String) -> LaunchAgentOutcome {
        var o = LaunchAgentOutcome(label: label, plist: Launchd.expand(plist))
        o.installed = FileManager.default.fileExists(atPath: o.plist)
        o.enabled = !Launchd.disabled(label)
        let printed = run(["launchctl", "print", Launchd.target(label)], timeout: 10)
        o.loaded = printed.ok
        guard printed.ok else { return o }
        for line in printed.out.split(separator: "\n", omittingEmptySubsequences: false) {
            guard line.hasPrefix("\t"), !line.hasPrefix("\t\t") else { continue }
            let field = line.dropFirst()
            if field.hasPrefix("state = ") { o.running = field.dropFirst(8) == "running" }
            if field.hasPrefix("pid = ") { o.pid = Int(field.dropFirst(6)) ?? 0 }
        }
        return o
    }
}

// MARK: - Actions

enum Act {
    /// Every action re-polls on completion, so acting on the menu visibly
    /// changes it. A non-zero exit raises an alert naming the command.
    static func run(_ argv: [String], then repoll: @escaping () -> Void) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome = Watcher.run(argv)
            DispatchQueue.main.async {
                if !outcome.ok { alert(argv.joined(separator: " "), outcome.err) }
                repoll()
            }
        }
    }

    static func open(_ target: String) {
        if let url = URL(string: target), url.scheme != nil {
            NSWorkspace.shared.open(url)
        } else {
            NSWorkspace.shared.open(URL(fileURLWithPath: (target as NSString).expandingTildeInPath))
        }
    }

    /// Text as the inside of a JSON string, for a hole in a post: body.
    static func jsonEscaped(_ s: String) -> String {
        var out = ""
        for u in s.unicodeScalars {
            switch u {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            case _ where u.value < 0x20: out += String(format: "\\u%04x", u.value)
            default: out.unicodeScalars.append(u)
            }
        }
        return out
    }

    /// Typed text as one query component. urlQueryAllowed leaves & + = alone,
    /// which would split the text into several parameters.
    static func urlQuery(_ s: String) -> String {
        let unreserved = CharacterSet(charactersIn:
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
        return s.addingPercentEncoding(withAllowedCharacters: unreserved) ?? ""
    }

    /// Hand-written Swift from menubar/Sources/. It re-polls like every other
    /// action, and raises no alert: there is no exit status to inspect, so
    /// reporting a failure belongs to the hook.
    static func swift(_ body: () -> Void, then repoll: @escaping () -> Void) {
        body()
        repoll()
    }

    static func post(_ urlString: String, body: String, then repoll: @escaping () -> Void) {
        guard let url = URL(string: urlString) else {
            alert("POST \(urlString)", "Not a URL.")
            return
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = body.data(using: .utf8)
        URLSession.shared.dataTask(with: request) { _, response, error in
            DispatchQueue.main.async {
                let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                if error != nil || !(200..<300).contains(status) {
                    alert("POST \(urlString)", error?.localizedDescription ?? "HTTP \(status)")
                }
                repoll()
            }
        }.resume()
    }

    /// The three things perch will do to a LaunchAgent. The verbs are the
    /// modern ones: `load`/`unload` also write launchd's disabled database,
    /// which is a second effect nobody asking for Start is asking for.
    static func agent(label: String, plist: String, verb: LaunchAgentVerb, then repoll: @escaping () -> Void) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome: RunOutcome
            switch verb {
            case .start:
                outcome = bootstrap(label: label, plist: plist)
            case .stop:
                outcome = Watcher.run(["launchctl", "bootout", Launchd.target(label)], timeout: 10)
            case .restart:
                outcome = restart(label: label, plist: plist)
            case .enable:
                outcome = Watcher.run(["launchctl", "enable", Launchd.target(label)], timeout: 10)
            case .disable:
                outcome = Watcher.run(["launchctl", "disable", Launchd.target(label)], timeout: 10)
            }
            DispatchQueue.main.async {
                if !outcome.ok { alert(verb.gerund + " " + label, outcome.err) }
                repoll()
            }
        }
    }

    /// bootout returns before launchd has let go of the label, and
    /// bootstrapping into that gap fails with Input/output error — so this
    /// polls until the label is genuinely gone rather than bootstrapping blind.
    private static func restart(label: String, plist: String) -> RunOutcome {
        _ = Watcher.run(["launchctl", "bootout", Launchd.target(label)], timeout: 10)
        for _ in 0..<40 {
            if !Watcher.run(["launchctl", "print", Launchd.target(label)], timeout: 10).ok {
                return bootstrap(label: label, plist: plist)
            }
            Thread.sleep(forTimeInterval: 0.05)
        }
        return RunOutcome(
            ok: false, code: -1, out: "",
            err: "launchd still holds \(label) after two seconds, so it was not bootstrapped again."
        )
    }

    /// launchd refuses to bootstrap a disabled label, and disabling is how a
    /// job is kept from starting at login — so starting one by hand enables
    /// it for the bootstrap and disables it again, which leaves it running.
    private static func bootstrap(label: String, plist: String) -> RunOutcome {
        let start = ["launchctl", "bootstrap", Launchd.domain, Launchd.expand(plist)]
        guard Launchd.disabled(label) else { return Watcher.run(start, timeout: 10) }
        let enabled = Watcher.run(["launchctl", "enable", Launchd.target(label)], timeout: 10)
        guard enabled.ok else { return enabled }
        let outcome = Watcher.run(start, timeout: 10)
        _ = Watcher.run(["launchctl", "disable", Launchd.target(label)], timeout: 10)
        return outcome
    }

    static func perform(_ action: MenuAction, then repoll: @escaping () -> Void) {
        switch action {
        case .run(let argv): run(argv, then: repoll)
        case .open(let target): open(target)
        case .post(let url, let body): post(url, body: body, then: repoll)
        case .agent(let label, let plist, let verb): agent(label: label, plist: plist, verb: verb, then: repoll)
        case .swift(let body): swift(body, then: repoll)
        case .window(let verb): Windows.perform(verb, then: repoll)
        case .quit: NSApp.terminate(nil)
        }
    }

    static func alert(_ command: String, _ detail: String) {
        let a = NSAlert()
        a.messageText = "\(command) failed"
        a.informativeText = detail.isEmpty ? "No output." : detail
        a.alertStyle = .warning
        a.runModal()
    }
}

// MARK: - Quitting

/// One answer in the quit prompt. A nil action just quits.
struct QuitChoice {
    let text: String
    let action: MenuAction?
}

/// What quitting asks. Cancel is implicit and always last; the first button is
/// the default.
struct QuitPrompt {
    let message: String
    let detail: String
    let buttons: [QuitChoice]
}

enum Quit {
    /// Quit reasons that mean the machine is going down or the user is walking
    /// away — nobody is asking this app a question, and nobody is waiting to
    /// answer one.
    private static let unattended: Set<OSType> = [
        OSType(kAELogOut), OSType(kAEReallyLogOut),
        OSType(kAEShutDown), OSType(kAERestart), OSType(kAEQuitAll),
    ]

    /// Whether this termination is aimed at this app specifically. An absent
    /// event or an absent reason means it is: NSApp.terminate from our own
    /// menus and from the Dock tile carries no quit reason at all.
    static func isUserInitiated(_ event: NSAppleEventDescriptor?) -> Bool {
        guard let reason = event?.attributeDescriptor(forKeyword: AEKeyword(kAEQuitReason)) else {
            return true
        }
        return !unattended.contains(reason.enumCodeValue)
    }

    /// Asks, and reports what to do. A helper that cancels someone's logout is
    /// worse than one that exits without asking, and a modal raised during
    /// shutdown is a dialog nobody is there to dismiss — so an unattended quit
    /// never reaches the alert.
    static func should(_ prompt: QuitPrompt?,
                       event: NSAppleEventDescriptor?,
                       then finish: @escaping (Bool) -> Void) -> NSApplication.TerminateReply {
        guard let prompt, isUserInitiated(event) else { return .terminateNow }

        let alert = NSAlert()
        alert.messageText = prompt.message
        alert.informativeText = prompt.detail
        let choices = prompt.buttons.isEmpty ? [QuitChoice(text: "Quit", action: nil)] : prompt.buttons
        for choice in choices {
            alert.addButton(withTitle: choice.text)
        }
        alert.addButton(withTitle: "Cancel").keyEquivalent = "\u{1b}"

        // The status item does not activate the app, so an unactivated modal can
        // sit behind another app with nothing to click while runModal blocks.
        NSApp.activate(ignoringOtherApps: true)

        let picked = alert.runModal().rawValue - NSApplication.ModalResponse.alertFirstButtonReturn.rawValue
        guard picked >= 0, picked < choices.count else { return .terminateCancel }
        guard let action = choices[picked].action else { return .terminateNow }

        // Captured strongly on purpose: every path out of this has to reply
        // exactly once, and a dropped reply hangs termination forever.
        Act.perform(action) { finish(true) }
        return .terminateLater
    }
}

/// The app's one window, if it declared one. Set at launch by the generated
/// Controller. A closure rather than a typed reference so Runtime.swift does not
/// depend on Window.swift, which is emitted only when there is a window.
enum Windows {
    static var handler: ((WindowVerb) -> Void)?

    static func perform(_ verb: WindowVerb, then repoll: @escaping () -> Void) {
        handler?(verb)
        repoll()
    }
}

// MARK: - Menu

/// An NSMenuItem that carries its own closure, so the generated menu builder
/// does not need a selector per action.
final class ActionItem: NSMenuItem {
    private let handler: () -> Void

    init(title: String, handler: @escaping () -> Void) {
        self.handler = handler
        super.init(title: title, action: nil, keyEquivalent: "")
        self.target = self
        self.action = #selector(fire)
    }

    @available(*, unavailable)
    required init(coder: NSCoder) { fatalError("not supported") }

    @objc private func fire() { handler() }
}

// MARK: - Face and menu

/// What the status item shows, decided from one poll's results.
struct Face {
    var icon: MenuIcon
    var tint: Tint? = nil
    var dim = false
    var badge = ""
}

/// What agent: does to a LaunchAgent. Closed, because each one is a launchctl
/// invocation perch writes rather than the author.
enum LaunchAgentVerb: String {
    case start, stop, restart, enable, disable

    var gerund: String {
        switch self {
        case .start: return "Starting"
        case .stop: return "Stopping"
        case .restart: return "Restarting"
        case .enable: return "Enabling"
        case .disable: return "Disabling"
        }
    }
}

/// What activating a menu item does. It is lowered when the menu is built, so
/// an item runs what it showed.
enum WindowVerb {
    case open
    case close
    case reload
}

enum MenuAction {
    case run([String])
    case open(String)
    case post(url: String, body: String)
    case agent(label: String, plist: String, verb: LaunchAgentVerb)
    case swift(() -> Void)
    case window(WindowVerb)
    case quit
}
